// Package gen writes a typed client for a vgraph schema: the code behind
// `vgraph gen`. It reads the schema the way the app does, by compiling a small
// program that registers every struct with an `edges()` method, and generates
// from what that program prints.
module gen

import json2
import os
import strings

// header starts every generated file, so `vgraph gen` knows which files it owns.
pub const header = '// Code generated by vgraph gen. DO NOT EDIT.'

// Entity is a struct that declares edges, found in the project's sources.
pub struct Entity {
pub:
	module_path string // the import path, such as `users.models`
	struct_name string // such as `User`
}

// alias is the name the generated code imports the entity's module as.
pub fn (e Entity) alias() string {
	return e.module_path.replace('.', '_')
}

// Column mirrors `vgraph.Column`, as the loader prints it.
pub struct Column {
pub:
	name         string
	field        string
	typ          string
	kind         string
	nullable     bool
	graphql_skip bool
	serial       bool
	optional     bool
	immutable    bool
	sensitive    bool
	unique       bool
	comment      string
	deprecated   string
	has_default  bool
	auto_update  bool
}

// Edge mirrors `vgraph.Edge`, as the loader prints it.
pub struct Edge {
pub:
	name       string
	kind       string
	to         string
	column     string
	type_col   string
	type_val   string
	through    string
	through_to string
	soft_del   string
}

// Table mirrors `vgraph.Table`, as the loader prints it.
pub struct Table {
pub:
	name         string
	struct_      string
	key          string
	columns      []Column
	edges        []Edge
	graphql_skip bool
}

fn (t Table) column(name string) !Column {
	for c in t.columns {
		if c.name == name {
			return c
		}
	}
	return error('`${t.name}` has no column `${name}`')
}

// discover returns the structs with an `edges() []vgraph.Edge` method in the
// project at `root`, sorted by module and name. It skips tests, hidden folders,
// the folders in `skip`, and folders that are projects of their own.
pub fn discover(root string, skip []string) ![]Entity {
	mut found := []Entity{}
	mut dirs := [root]
	for dirs.len > 0 {
		dir := dirs.pop()
		for name in os.ls(dir)! {
			path := os.join_path(dir, name)
			if os.is_dir(path) {
				if !name.starts_with('.') && name !in skip
					&& !os.exists(os.join_path(path, 'v.mod')) {
					dirs << path
				}
				continue
			}
			if !name.ends_with('.v') || name.ends_with('_test.v') {
				continue
			}
			for line in os.read_lines(path)! {
				struct_name := edges_receiver(line) or { continue }
				rel := dir.all_after(root).trim_left(os.path_separator)
				if rel == '' {
					return error('${path}: `${struct_name}` is in the main module, which the generated client cannot import; move it to a module')
				}
				found << Entity{
					module_path: rel.replace(os.path_separator, '.')
					struct_name: struct_name
				}
			}
		}
	}
	found.sort_with_compare(fn (a &Entity, b &Entity) int {
		ka := '${a.module_path}.${a.struct_name}'
		kb := '${b.module_path}.${b.struct_name}'
		return compare_strings(&ka, &kb)
	})
	return found
}

// edges_receiver returns `User` for a line such as
// `pub fn (u User) edges() []vgraph.Edge {`, and `none` for any other line.
fn edges_receiver(line string) ?string {
	text := line.trim_space()
	if !(text.starts_with('fn (') || text.starts_with('pub fn (')) {
		return none
	}
	receiver := text.all_after('(').all_before(')')
	rest := text.all_after(receiver + ')').replace(' ', '')
	if !rest.starts_with('edges()[]vgraph.Edge') {
		return none
	}
	name := receiver.fields().last().trim_left('&')
	return if name == '' { none } else { name }
}

// loader_source returns a program that registers `entities` with a schema,
// checks it, and prints its tables as JSON.
pub fn loader_source(entities []Entity) string {
	mut b := strings.new_builder(1024)
	b.writeln('module main\n')
	b.writeln('import json2')
	b.writeln('import five07.vgraph')
	for path in imports_of(entities) {
		b.writeln('import ${import_line(path)}')
	}
	b.writeln('\nfn main() {')
	b.writeln('\tmut schema := vgraph.Schema{}')
	for e in entities {
		b.writeln('\tschema.add[${e.alias()}.${e.struct_name}]() or { problems(err) }')
	}
	b.writeln('\tschema.validate() or { problems(err) }')
	b.writeln('\tprintln(json2.encode(schema.tables()))')
	b.writeln('}')
	b.writeln('\n// problems reports what is wrong with the schema, with the exit code 2.')
	b.writeln('fn problems(err IError) {')
	b.writeln('\teprintln(err.msg())')
	b.writeln('\texit(2)')
	b.writeln('}')
	return b.str()
}

fn imports_of(entities []Entity) []string {
	mut paths := []string{}
	for e in entities {
		if e.module_path !in paths {
			paths << e.module_path
		}
	}
	return paths
}

// import_line returns what follows `import` for the module `path`: the path,
// and the alias the generated code uses when it differs, as in
// `users.models as users_models`.
fn import_line(path string) string {
	alias := path.replace('.', '_')
	return if alias == path { path } else { '${path} as ${alias}' }
}

// decode_tables reads what the loader printed.
pub fn decode_tables(text string) ![]Table {
	return json2.decode[[]Table](text)!
}
